import kotlin.math.sqrt
import kotlin.math.floor

fun funkyNumbers(n: Long): String {
    var funkyNumber = "NO"
    val maxTriangle = maxTrianglePossible(n)

    for (i in maxTriangle downTo 1) {
        val firstTriangle = triangleNumbers(i)
        val rem = n - firstTriangle

        if (rem == 0L) continue

        val secFactor = maxTrianglePossible(rem)
        val secTriangle = triangleNumbers(secFactor)

        val triangles = firstTriangle + secTriangle

        if (triangles == n) {
            funkyNumber = "YES"
            break
        }
    }
    return funkyNumber
}

fun maxTrianglePossible(n: Long): Long {
    if (n <= 0) return 0
    val k = floor(sqrt(n * 2.0)).toLong()
    return k
}

fun triangleNumbers(x: Long): Long {
    return x * (x + 1) / 2
}

